std::vector<std::uint8_t> EncodeSblrSecurityCreatePrivilegeTemplateResultV1(const SblrSecurityCreatePrivilegeTemplateResultV1&v){if(!nonzero(v.body)||!v.availability||!nonzero(v.publication_barrier))return{};auto o=hdr("PTRS",320);o.insert(o.end(),v.body.begin(),v.body.end());auto e=sha("ScratchBird.SblrSecurityCreatePrivilegeTemplateResult.V1",o.data()+16,240);if(nonzero(v.evidence)&&e!=v.evidence)return{};o.insert(o.end(),e.begin(),e.end());put(o,v.availability,8);o.insert(o.end(),v.publication_barrier.begin(),v.publication_barrier.end());o.insert(o.end(),8,0);return o;}
